from typing import Annotated, Literal, Optional
from langchain_core.messages import BaseMessage
from langgraph.graph import add_messages
from pydantic import BaseModel, Field
from typing_extensions import TypedDict

# ==========================================
# 1. Supervisor Structured Output (Pydantic)
# ==========================================


class SupervisorResponse(BaseModel):
    """Structured response schema generated by the Supervisor Agent to control system execution flow."""

    response_to_user: Optional[str] = Field(
        default=None,
        description=(
            "Direct final response to present to the user. "
            "MUST be populated if asking the user for missing details or presenting final results. "
            "MUST be None if delegating a task to a subagent in 'next'."
        ),
    )

    next: Optional[
        Literal[
            "budget_expert",
            "weather_expert",
            "attractions_expert",
            "accommodation_expert",
            "transportation_expert",
            "END",
        ]
    ] = Field(
        default=None,
        description=(
            "The specific subagent to execute next. "
            "Set to 'END' when all workflow tasks are complete. "
            "Set to None if giving a direct 'response_to_user'."
        ),
    )

    origin: Optional[str] = Field(
        default=None,
        description=(
            "The departure or origin city/location extracted or updated from user context. "
            "Leave None if not mentioned yet or unchanged."
        ),
    )

    destination: Optional[str] = Field(
        default=None,
        description=(
            "The primary arrival or target destination extracted or updated from user context. "
            "Leave None if not mentioned yet or unchanged."
        ),
    )

    budget: Optional[float] = Field(
        default=None,
        description=(
            "Total allocated monetary budget extracted or updated from user context (numeric value only). "
            "Leave None if not mentioned yet or unchanged."
        ),
    )

    task: Optional[str] = Field(
        default=None,
        description=(
            "A precise, self-contained instruction for the delegated subagent specified in 'next'. "
            "Must contain all necessary parameters, available through user context (dates, places, constraints) so the worker can execute without message history."
        ),
    )


# ==========================================
# 2. LangGraph Global State Schema
# ==========================================


class AgentState(TypedDict):
    """Global multi-agent state maintained across graph execution nodes."""

    messages: Annotated[list[BaseMessage], add_messages]
    origin: Optional[str]
    destination: Optional[str]
    budget: Optional[float]
    task: Optional[str]